public async Task<CustomerLinkedOrderResponse> Handle(LinkCustomerOrderCommand command, CancellationToken cancellationToken)
    {
        if (!currentUser.IsAuthenticated || currentUser.UserId is null)
        {
            throw new UnauthorizedAccessException("Authenticated user context is required.");
        }

        var order = await dbContext.Orders
            .Include(candidate => candidate.TourTimeSlot)
            .ThenInclude(candidate => candidate!.Tour)
            .SingleAsync(candidate => candidate.Uuid == command.OrderUuid, cancellationToken);

        if (command.LinkUser)
        {
            order.UserId = currentUser.UserId.Value;
            order.Updated = DateTime.UtcNow;
        }

        var user = await dbContext.Users.SingleAsync(candidate => candidate.Id == currentUser.UserId.Value, cancellationToken);
        var paymentEventTypeId = await CustomerCheckoutSupport.ResolveEventTypeIdAsync(dbContext, "payment", cancellationToken);
        if (paymentEventTypeId.HasValue)
        {
            var exists = await dbContext.EventSyncEntries.AsNoTracking()
                .AnyAsync(candidate => candidate.UserId == user.Id && candidate.EventTypeId == paymentEventTypeId.Value && candidate.Params != null && candidate.Params.Contains(command.OrderUuid), cancellationToken);
            if (!exists)
            {
                dbContext.EventSyncEntries.Add(new EventSync
                {
                    UserId = user.Id,
                    Email = user.Email,
                    EventTypeId = paymentEventTypeId.Value,
                    Params = $"{{\"_PurchaseID\":\"{command.OrderUuid}\",\"_OrderTotal\":\"{order.Total:0.00}\"}}",
                    CreatedAt = DateTime.UtcNow,
                    UpdatedAt = DateTime.UtcNow
                });
            }
        }

        await dbContext.SaveChangesAsync(cancellationToken);
        return new CustomerLinkedOrderResponse(order.Uuid, $"/order-photos/{order.Uuid}", CustomerCheckoutSupport.ResolveHomepageLink(order.TourTimeSlot!.Tour!, options.Value), order.QrCode);
    }

