    public Task<CustomerLinkedOrderResponse> Linked([FromBody] LinkedOrderRequest request, CancellationToken cancellationToken)
    {
        return linkCustomerOrderCommandHandler.Handle(new LinkCustomerOrderCommand(request.OrderId, request.ShouldLink), cancellationToken);
    }

